import torch


def run(x, dim, keepdim):
    return torch.mode(x, dim=dim, keepdim=keepdim)


def gen_inputs(ctx, device):
    shape = tuple(ctx["x__shape"])
    dtype = getattr(torch, ctx["x__dtype"])
    if dtype in (torch.float16, torch.float32, torch.bfloat16):
        x = torch.randn(shape, dtype=dtype, device=device)
    else:
        x = torch.randint(-100, 100, shape, dtype=dtype, device=device)
    return {"x": x}


def valid(ref_outputs, sol_outputs, inputs, ctx):
    ref_val = ref_outputs[0].detach().to("cpu")
    sol_val = sol_outputs[0].detach().to("cpu")
    sol_idx = sol_outputs[1].detach().to("cpu")
    inp = inputs[0].detach().to("cpu")
    dim = inputs[1]
    ndim = inp.dim()
    if dim < 0:
        dim += ndim
    if ref_val.shape != sol_val.shape:
        return {"passed": False, "message": f"value shape {tuple(sol_val.shape)} vs {tuple(ref_val.shape)}", "metrics": {}}
    if not torch.equal(ref_val, sol_val):
        return {"passed": False, "message": "mode values mismatch", "metrics": {}}
    gather_shape = list(inp.shape[:dim]) + [1] + list(inp.shape[dim + 1:])
    gather_idx = sol_idx.reshape(gather_shape)
    values_at_index = inp.gather(dim, gather_idx).reshape(sol_val.shape)
    if not torch.equal(values_at_index, ref_val):
        return {"passed": False, "message": "index does not point to mode value", "metrics": {}}
    return {"passed": True, "message": "", "metrics": {}}
